import 'dart:convert';

class AgreedNegotiation {
	dynamic id;
	dynamic textOfTheAgreement;
	dynamic createdAt;

	AgreedNegotiation({this.id, this.textOfTheAgreement, this.createdAt});

	factory AgreedNegotiation.(Map<String, dynamic> data) {
		return AgreedNegotiation(
			id: data['id'] as dynamic,
			textOfTheAgreement: data['Text_of_the_agreement'] as dynamic,
			createdAt: data['created_at'] as dynamic,
		);
	}



	Map<String, dynamic> () {
		return {
			'id': id,
			'Text_of_the_agreement': textOfTheAgreement,
			'created_at': createdAt,		};
	}

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [AgreedNegotiation].
	factory AgreedNegotiation.fromJson(String data) {
		return AgreedNegotiation.(json.decode(data) as Map<String, dynamic>);
	}
  /// `dart:convert`
  ///
  /// Converts [AgreedNegotiation] to a JSON string.
	String toJson() => json.encode(());
}
